import React, { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { fetchStaffCommands, type StaffCommandData } from "../../services/api";
import styles from "./StaffHelpPage.module.css";

type TabType = "help" | "services";

const services = [
  { title: "Staff AI", description: "トークン・速度統計と会話メモリーの閲覧、編集、削除。", path: "/staff/ai", icon: "psychology" },
  {
    title: "AIサーバー構築",
    description: "AIに依頼してチャンネル・カテゴリの作成や権限設定のプランを作り、確認してから適用します。",
    path: "/staff/server-builder",
    icon: "construction",
  },
  {
    title: "AntiCheat",
    description: "不正検知ルールと自動処罰の設定面へ移動します。",
    path: "/staff/anticheat",
    icon: "shield",
  },
  {
    title: "プライベートチャット",
    description: "ユーザーとの個別対応を安全に管理します。",
    path: "/staff/privatechat",
    icon: "forum",
  },
  {
    title: "ロール管理",
    description: "ロールプリセットと変更ログを整理します。",
    path: "/staff/rolemanager",
    icon: "style",
  },
  {
    title: "Core パネル",
    description: "性格診断・オセロ・リクエストのパネルを管理します。",
    path: "/staff/corepanel",
    icon: "dashboard",
  },
  {
    title: "ランキング管理",
    description: "XP とパネル運用の設定に進みます。",
    path: "/staff/rankmanager",
    icon: "leaderboard",
  },
  {
    title: "Todo",
    description:
      "Discord チャンネルに進行管理 Todo を Embed で保存・更新します。",
    path: "/staff/todo",
    icon: "checklist",
  },
  {
    title: "参加・退出ログ",
    description:
      "メンバー参加・退出通知の送信先とEmbedテンプレートを設定します。",
    path: "/staff/join-log",
    icon: "login",
  },
];

const serviceCategories: Record<string, string> = {
  "/staff/ai": "community",
  "/staff/server-builder": "manage",
  "/staff/anticheat": "safety",
  "/staff/privatechat": "safety",
  "/staff/join-log": "safety",
  "/staff/rolemanager": "manage",
  "/staff/todo": "manage",
  "/staff/corepanel": "community",
  "/staff/rankmanager": "community",
};
const categories = [
  { id: "all", label: "すべてのツール", icon: "grid_view" },
  { id: "safety", label: "モデレーション", icon: "shield" },
  { id: "manage", label: "サーバー管理", icon: "tune" },
  { id: "community", label: "コミュニティ", icon: "groups" },
];

const StaffHelpPage: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<TabType>("services");
  const [commandData, setCommandData] = useState<StaffCommandData | null>(null);
  const [expandedCommand, setExpandedCommand] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [serviceQuery, setServiceQuery] = useState("");
  const [category, setCategory] = useState("all");

  useEffect(() => {
    const load = async () => {
      try {
        const data = await fetchStaffCommands();
        setCommandData(data);
      } catch (loadError) {
        console.error("Failed to load staff commands:", loadError);
        setError(
          loadError instanceof Error
            ? loadError.message
            : "読み込みに失敗しました",
        );
      } finally {
        setLoading(false);
      }
    };

    load();
  }, []);

  const filteredCommands = useMemo(() => {
    if (!commandData) {
      return [];
    }

    const keyword = searchQuery.trim().toLowerCase();
    if (!keyword) {
      return commandData.subcommands;
    }

    return commandData.subcommands.filter((command) => {
      const searchable = [
        command.name,
        command.description,
        ...command.options.map(
          (option) => `${option.name} ${option.description} ${option.type}`,
        ),
      ]
        .join(" ")
        .toLowerCase();

      return searchable.includes(keyword);
    });
  }, [commandData, searchQuery]);

  const getOptionIcon = (type: string) => {
    const icons: Record<string, string> = {
      STRING: "title",
      INTEGER: "pin",
      BOOLEAN: "toggle_on",
      USER: "person",
      CHANNEL: "tag",
      ROLE: "shield",
      MENTIONABLE: "alternate_email",
      NUMBER: "calculate",
    };

    return icons[type] || "extension";
  };

  const renderBody = () => {
    if (activeTab === "services") {
      return (
        <div className={styles.servicesGrid}>
          {services
            .filter(
              (service) =>
                (category === "all" ||
                  serviceCategories[service.path] === category) &&
                `${service.title} ${service.description}`
                  .toLowerCase()
                  .includes(serviceQuery.toLowerCase().trim()),
            )
            .map((service) => (
              <button
                key={service.path}
                className={styles.serviceCard}
                onClick={() => navigate(service.path)}
                type="button"
              >
                <span className={styles.serviceIcon}>
                  <span className="material-icons" aria-hidden="true">
                    {service.icon}
                  </span>
                </span>
                <div>
                  <h3>{service.title}</h3>
                  <p>{service.description}</p>
                </div>
                <span className="material-icons" aria-hidden="true">
                  arrow_forward
                </span>
              </button>
            ))}
        </div>
      );
    }

    if (loading) {
      return (
        <div className={styles.statePanel}>
          スタッフ機能を読み込んでいます...
        </div>
      );
    }

    if (error || !commandData) {
      return (
        <div className={styles.statePanel}>
          {error || "データの取得に失敗しました"}
        </div>
      );
    }

    return (
      <>
        <div className={styles.searchBox}>
          <span className="material-icons" aria-hidden="true">
            search
          </span>
          <input
            className={styles.searchInput}
            type="text"
            value={searchQuery}
            onChange={(event) => setSearchQuery(event.target.value)}
            aria-label="コマンドを検索"
            placeholder="コマンド名・説明・オプションを検索"
          />
        </div>

        <div className={styles.commandList}>
          {filteredCommands.length === 0 ? (
            <div className={styles.statePanel}>
              該当するコマンドがありません。
            </div>
          ) : (
            filteredCommands.map((command) => {
              const isOpen = expandedCommand === command.name;
              return (
                <article key={command.name} className={styles.commandCard}>
                  <button
                    className={styles.commandHeader}
                    onClick={() =>
                      setExpandedCommand(isOpen ? null : command.name)
                    }
                    type="button"
                    aria-expanded={isOpen}
                  >
                    <div>
                      <span className={styles.commandName}>
                        /staff {command.name}
                      </span>
                      <p>{command.description}</p>
                    </div>
                    <span className="material-icons" aria-hidden="true">
                      {isOpen ? "remove" : "add"}
                    </span>
                  </button>

                  {isOpen ? (
                    <div className={styles.commandBody}>
                      {command.options.length > 0 ? (
                        <div className={styles.optionList}>
                          {command.options.map((option) => (
                            <div
                              key={option.name}
                              className={styles.optionCard}
                            >
                              <div className={styles.optionHeader}>
                                <span className={styles.optionIcon}>
                                  <span
                                    className="material-icons"
                                    aria-hidden="true"
                                  >
                                    {getOptionIcon(option.type)}
                                  </span>
                                </span>
                                <div>
                                  <strong>{option.name}</strong>
                                  <span className={styles.optionType}>
                                    {option.type}
                                  </span>
                                </div>
                                {option.required ? (
                                  <span className={styles.requiredBadge}>
                                    必須
                                  </span>
                                ) : null}
                              </div>
                              <p>{option.description}</p>
                              {option.choices.length > 0 ? (
                                <div className={styles.choiceList}>
                                  {option.choices.map((choice) => (
                                    <span
                                      key={String(choice.value)}
                                      className={styles.choiceBadge}
                                    >
                                      {choice.name}
                                    </span>
                                  ))}
                                </div>
                              ) : null}
                            </div>
                          ))}
                        </div>
                      ) : (
                        <p className={styles.commandNote}>
                          追加オプションはありません。
                        </p>
                      )}

                      <div className={styles.usageBox}>
                        <span className={styles.usageLabel}>Usage</span>
                        <code>
                          /staff {command.name}
                          {command.options
                            .filter((option) => option.required)
                            .map((option) => ` ${option.name}:<値>`)
                            .join("")}
                        </code>
                      </div>
                    </div>
                  ) : null}
                </article>
              );
            })
          )}
        </div>
      </>
    );
  };

  return (
    <div className={styles.page}>
      <header className={styles.pageHeader}>
        <div>
          <span className={styles.pageEyebrow}>STAFF CONSOLE</span>
          <h1>スタッフツール</h1>
          <p>サーバーの日常を支える、運営の道具箱。</p>
        </div>
        <button
          className={styles.serverLink}
          type="button"
          onClick={() => navigate("/settings")}
        >
          サーバーを選ぶ <span aria-hidden="true">↗</span>
        </button>
      </header>
      <div className={styles.workspace}>
        <aside className={styles.sidebar}>
          <span className={styles.navLabel}>ツールを探す</span>
          <nav className={styles.categoryNav} aria-label="スタッフツールの分類">
            {categories.map((item) => (
              <button
                key={item.id}
                type="button"
                aria-pressed={activeTab === "services" && category === item.id}
                className={
                  activeTab === "services" && category === item.id
                    ? styles.activeCategory
                    : ""
                }
                onClick={() => {
                  setCategory(item.id);
                  setActiveTab("services");
                }}
              >
                <span className="material-icons" aria-hidden="true">
                  {item.icon}
                </span>
                {item.label}
                <small>
                  {item.id === "all"
                    ? services.length
                    : services.filter(
                        (s) => serviceCategories[s.path] === item.id,
                      ).length}
                </small>
              </button>
            ))}
          </nav>
          <div className={styles.reference}>
            <span className={styles.navLabel}>リファレンス</span>
            <button
              type="button"
              className={activeTab === "help" ? styles.activeCategory : ""}
              aria-pressed={activeTab === "help"}
              onClick={() => setActiveTab("help")}
            >
              <span className="material-icons" aria-hidden="true">
                terminal
              </span>
              コマンド一覧
            </button>
            <p>
              Discordでは <code>/staff</code> から
              <br />
              各コマンドを実行できます。
            </p>
          </div>
        </aside>
        <section
          className={styles.content}
          aria-label={
            activeTab === "services" ? "管理ツール一覧" : "コマンド一覧"
          }
        >
          <div className={styles.contentHeader}>
            <div>
              <h2>
                {activeTab === "services"
                  ? categories.find((c) => c.id === category)?.label
                  : "コマンド一覧"}
              </h2>
              <p>
                {activeTab === "services"
                  ? "使いたい機能を選んで、設定をはじめましょう。"
                  : "コマンドを選ぶと使い方とオプションを確認できます。"}
              </p>
            </div>
            <span>
              {activeTab === "services"
                ? "TOOLS"
                : `${commandData?.subcommands.length ?? "—"} COMMANDS`}
            </span>
          </div>
          {activeTab === "services" && (
            <label className={styles.searchBox}>
              <span className="material-icons" aria-hidden="true">
                search
              </span>
              <input
                aria-label="ツールを検索"
                className={styles.searchInput}
                placeholder="ツール名で検索"
                value={serviceQuery}
                onChange={(e) => setServiceQuery(e.target.value)}
              />
            </label>
          )}
          {activeTab === "services" &&
            !services.some(
              (service) =>
                (category === "all" ||
                  serviceCategories[service.path] === category) &&
                `${service.title} ${service.description}`
                  .toLowerCase()
                  .includes(serviceQuery.toLowerCase().trim()),
            ) && (
              <div className={styles.statePanel}>
                該当するツールがありません。検索語や分類を変更してください。
              </div>
            )}
          {renderBody()}
        </section>
      </div>
    </div>
  );
};
export default StaffHelpPage;
