type Guild = { id: string; name: string };
type Metrics = {
  requests: number; inputTokens: number; outputTokens: number;
  totalTokens: number; generatedSeconds: number; timedOutputTokens?: number;
  cacheHitTokens: number; cacheInputTokens: number;
  startedAt?: string | null;
  byPurpose?: Record<string, { requests: number; totalTokens: number }>;
};
const purposeLabels: Record<string, string> = {
  'staff-ai': '/staff ai', 'staff-ai-scheduled': '予約タスク', 'chat-ai': 'ChatAI',
  'dot-judge': 'dot判定', 'dot-generate': 'dot生成', 'dot-learn': 'dot学習',
  media: 'メディア説明', vision: '画像解析', episode: '出来事抽出', persona: '性格生成',
  'content-safety': 'コンテンツ安全判定', 'server-builder': 'サーバー構築', memory: '会話要約',
  corepanel: '性格診断など', embedding: '埋め込み', other: 'その他',
};
type Memory = {
  id: string; kind: 'daily' | 'user'; guildId: string; userId?: string; day?: string;
  title: string; content: string; publicInterests?: string; evidenceCount: number;
  updatedAt: string; editedByStaff?: boolean; sourceChannelName?: string;
};
type PersonalitySettings = {
  learningEnabled: boolean;
  tone: 'auto' | 'casual' | 'balanced' | 'polite';
  humor: 'auto' | 'low' | 'medium' | 'high';
  emoji: 'auto' | 'low' | 'medium' | 'high';
  verbosity: 'auto' | 'brief' | 'normal' | 'detailed';
  customInstructions: string;
};
type Persona = {
  name: string; character: string; speakingStyle: string; behavior: string;
  generatedAt: string; source: 'generated' | 'default';
  firstPerson?: string; exampleLines?: string[]; catchphrases?: string[];
  likes?: string; dislikes?: string; interactionStrengths?: string;
  weakTopicReaction?: string; avoidBehaviors?: string[];
};
type Personality = PersonalitySettings & {
  learnedSummary: string; learnedMessageCount: number; learningRevision: number; updatedAt: string;
  persona?: Persona;
};
const defaultPersonality: Personality = {
  learningEnabled: true, tone: 'auto', humor: 'auto', emoji: 'auto', verbosity: 'auto',
  customInstructions: '', learnedSummary: '', learnedMessageCount: 0, learningRevision: 0, updatedAt: '',
};
const zero: Metrics = { requests: 0, inputTokens: 0, outputTokens: 0, totalTokens: 0,
  generatedSeconds: 0, timedOutputTokens: 0, cacheHitTokens: 0, cacheInputTokens: 0, startedAt: null, byPurpose: {} };
const fmt = (n: number) => {
  const value = Math.round(n);
  const absolute = Math.abs(value);
  const compact = (scaled: number, suffix: 'K' | 'M') =>
    scaled.toFixed(2).replace(/\.?0+$/, '') + suffix;
  if (absolute >= 999_995) return compact(value / 1_000_000, 'M');
  if (absolute >= 1_000) return compact(value / 1_000, 'K');
  return value.toLocaleString('ja-JP');
};
const icon = (value: string, className = '') =>
  <span className={`material-icons ${className || ui.icon}`} aria-hidden="true">{value}</span>;

async function readJson(url: string, options?: RequestInit) {
  // body があるのに Content-Type が無いと、fetch の文字列 body は text/plain になり
  // サーバーの express.json() が body を読まないため、送信したはずの値
  // （性格プレビューの direction や適用の previewId）がサーバーへ届かなくなる。
  // services/api.ts の apiRequest と同じく、body がある場合は JSON を既定にする。
  const headers = new Headers(options?.headers);
  if (options?.body != null && !headers.has('Content-Type')) {
    headers.set('Content-Type', 'application/json');
  }
  const r = await fetch(url, { credentials: 'include', cache: 'no-store', ...options, headers });
  const body = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error(body.error || `HTTP ${r.status}`);
  return body;
}

type MemberMemoItem = {
  userId: string; name: string; memo: string;
  messageCount: number; updatedAt: string; lastSeenAt: number;
};

/** 長文を数行に畳んで表示し、必要なときだけ全文に広げる（ライブラリが増えても縦に伸び続けないため）。 */
const ClampText: React.FC<{ text: string; className?: string; style?: React.CSSProperties }> = ({ text, className, style }) => {
  const [open, setOpen] = useState(false);
  const long = text.length > 240;
  return <div style={style}>
    <p className={`${className ?? ''} ${long && !open ? styles.clamped : ''}`}>{text}</p>
    {long && <button type="button" className={styles.moreButton} onClick={() => setOpen(v => !v)}>
      {open ? '閉じる' : '全文を表示'}
    </button>}
  </div>;
};

/**
 * セクションの折りたたみ。詳細系は初期状態で閉じ、見出しだけでも内容が分かるように
 * 説明文とバッジは閉じた状態でも見せる。開いたときだけ中身を描画する。
 */
const CollapsibleSection: React.FC<{
  eyebrow: React.ReactNode;
  title: string;
  description?: string;
  badge?: React.ReactNode;
  headerActions?: React.ReactNode;
  defaultOpen?: boolean;
  children: React.ReactNode;
}> = ({ eyebrow, title, description, badge, headerActions, defaultOpen = false, children }) => {
  const [open, setOpen] = useState(defaultOpen);
  return <section className={ui.panel} aria-label={title}>
    <div className={`${ui.sectionHeader} ${open ? '' : styles.headerClosed}`}>
      <button type="button" className={styles.sectionToggle} aria-expanded={open} onClick={() => setOpen(v => !v)}>
        <span className={styles.sectionToggleText}>
          <span>{eyebrow}</span>
          <span className={styles.sectionTitle}>{title}</span>
          {description ? <span className={styles.sectionDesc}>{description}</span> : null}
        </span>
        <span className={`material-icons ${styles.chevron} ${open ? styles.chevronOpen : ''}`} aria-hidden="true">expand_more</span>
      </button>
      {badge}
      {headerActions}
    </div>
    {open ? children : null}
  </section>;
};

const PersonaDetails: React.FC<{ persona: Persona }> = ({ persona }) => (
  <>
    <p><b>{persona.name}</b>{persona.firstPerson ? `（一人称：${persona.firstPerson}）` : ''}：{persona.character}</p>
    <p>話し方：{persona.speakingStyle}</p>
    {persona.exampleLines?.length ? <p>口調の例：{persona.exampleLines.map(line => `「${line}」`).join(' ')}</p> : null}
    {persona.catchphrases?.length ? <p>口癖：{persona.catchphrases.join('、')}</p> : null}
    {persona.likes ? <p>好きなもの・話題：{persona.likes}</p> : null}
    {persona.dislikes ? <p>苦手なもの・話題：{persona.dislikes}</p> : null}
    {persona.interactionStrengths ? <p>得意な絡み方：{persona.interactionStrengths}</p> : null}
    {persona.weakTopicReaction ? <p>苦手な話題への反応：{persona.weakTopicReaction}</p> : null}
    <p>振る舞い：{persona.behavior}</p>
    {persona.avoidBehaviors?.length ? <p>避ける振る舞い：{persona.avoidBehaviors.join('、')}</p> : null}
  </>
);

const StaffAIPage: React.FC = () => {
  const { addToast } = useAppToast();
  const [guilds, setGuilds] = useState<Guild[]>([]);
  const [guildId, setGuildId] = useState('');
  const selectedGuildRef = useRef(guildId);
  selectedGuildRef.current = guildId;
  const [metrics, setMetrics] = useState<Metrics>(zero);
  const [memories, setMemories] = useState<Memory[]>([]);
  const [personality, setPersonality] = useState<Personality>(defaultPersonality);
  const [personalityDraft, setPersonalityDraft] = useState<PersonalitySettings>(defaultPersonality);
  const [personalityDirty, setPersonalityDirty] = useState(false);
  const personalityDirtyRef = useRef(false);
  const [loadingGuilds, setLoadingGuilds] = useState(true);
  const [loading, setLoading] = useState(false);
  const [busy, setBusy] = useState(false);
  const [personalityBusy, setPersonalityBusy] = useState(false);
  const [personaBusy, setPersonaBusy] = useState(false);
  const [personaDirection, setPersonaDirection] = useState('');
  const [personaPreview, setPersonaPreview] = useState<{ previewId: string; persona: Persona } | null>(null);
  const [personaPreviewBusy, setPersonaPreviewBusy] = useState(false);
  const [personaApplyBusy, setPersonaApplyBusy] = useState(false);
  const [resetPersonalityConfirm, setResetPersonalityConfirm] = useState(false);
  const [error, setError] = useState('');
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const tab = 'daily' as const;
  const [customMemos, setCustomMemos] = useState<Array<{id:string;title?:string;content:string;authorName?:string;createdAt:string;updatedAt?:string}>>([]);
  const [search, setSearch] = useState('');
  const [editing, setEditing] = useState<string | null>(null);
  const [draft, setDraft] = useState('');
  const [deleting, setDeleting] = useState<Memory | 'all' | null>(null);
  const [confirmation, setConfirmation] = useState('');
  const [memberMemos, setMemberMemos] = useState<MemberMemoItem[]>([]);
  const [memberMemoCanManage, setMemberMemoCanManage] = useState(false);
  const [memberMemoSearch, setMemberMemoSearch] = useState('');
  const [memberMemoBusyId, setMemberMemoBusyId] = useState<string | null>(null);

  const updatePersonalityDraft = (next: PersonalitySettings) => {
    personalityDirtyRef.current = true;
    setPersonalityDirty(true);
    setPersonalityDraft(next);
  };

  useEffect(() => {
    let active = true;
    void readJson('/api/staff/guilds')
      .then(data => {
        if (!active) return;
        const list = (data.guilds || []) as Guild[];
        setGuilds(list);
        setGuildId(list[0]?.id ?? '');
      })
      .catch(err => { if (active) setError(err instanceof Error ? err.message : 'サーバー一覧の取得に失敗しました'); })
      .finally(() => { if (active) setLoadingGuilds(false); });
    return () => { active = false; };
  }, []);

  const refresh = useCallback(async (selectedGuild: string, showLoading = false) => {
    if (!selectedGuild) return;
    if (showLoading) setLoading(true);
    try {
      const data = await readJson(`/api/staff/ai/${selectedGuild}`);
      if (selectedGuild !== selectedGuildRef.current) return;
      setMetrics(data.metrics ?? zero);
      setMemories(data.memories ?? []);
      setCustomMemos(data.customMemos ?? []);
      try {
        const memoData = await readJson(`/api/staff/ai/${selectedGuild}/member-memos`);
        if (selectedGuild === selectedGuildRef.current) {
          setMemberMemos(Array.isArray(memoData.memos) ? memoData.memos as MemberMemoItem[] : []);
          setMemberMemoCanManage(!!memoData.canManage);
        }
      } catch { /* メンバーメモは補助表示のため、失敗してもページ全体は止めない */ }
      const nextPersonality = data.personality ?? defaultPersonality;
      setPersonality(nextPersonality);
      if (showLoading || !personalityDirtyRef.current) {
        personalityDirtyRef.current = false;
        setPersonalityDirty(false);
        setPersonalityDraft({
          learningEnabled: nextPersonality.learningEnabled,
          tone: nextPersonality.tone,
          humor: nextPersonality.humor,
          emoji: nextPersonality.emoji,
          verbosity: nextPersonality.verbosity,
          customInstructions: nextPersonality.customInstructions,
        });
      }
      setLastUpdated(new Date());
      setError('');
    } catch (e) {
      setError(e instanceof Error ? e.message : 'データの取得に失敗しました');
    } finally {
      if (showLoading) setLoading(false);
    }
  }, [guildId]);

  const savePersonality = async () => {
    const selectedGuild = guildId;
    if (!selectedGuild || personalityBusy) return;
    setPersonalityBusy(true);
    try {
      const data = await readJson(`/api/staff/ai/${selectedGuild}/personality`, {
        method: 'PUT', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(personalityDraft),
      });
      if (selectedGuild === selectedGuildRef.current) {
        const next = data.personality as Personality;
        setPersonality(next);
        personalityDirtyRef.current = false; setPersonalityDirty(false);
        setPersonalityDraft({
          learningEnabled: next.learningEnabled, tone: next.tone, humor: next.humor,
          emoji: next.emoji, verbosity: next.verbosity, customInstructions: next.customInstructions,
        });
        addToast('AIの話し方を保存しました', 'success');
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : 'AIの話し方を保存できませんでした');
      addToast('AIの話し方を保存できませんでした', 'error');
    } finally { setPersonalityBusy(false); }
  };

  const regeneratePersona = async () => {
    const selectedGuild = guildId;
    if (!selectedGuild || personaBusy) return;
    setPersonaBusy(true);
    try {
      const data = await readJson(`/api/staff/ai/${selectedGuild}/personality/persona/regenerate`, { method: 'POST' });
      if (selectedGuild === selectedGuildRef.current) {
        setPersonality(data.personality as Personality);
        addToast('AIが新しい性格を決めました', 'success');
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : 'AIの性格を再生成できませんでした');
      addToast('AIの性格を再生成できませんでした', 'error');
    } finally { setPersonaBusy(false); }
  };

  const previewPersona = async () => {
    const selectedGuild = guildId;
    if (!selectedGuild || personaPreviewBusy) return;
    setPersonaPreviewBusy(true);
    try {
      const data = await readJson(`/api/staff/ai/${selectedGuild}/personality/persona/preview`, {
        method: 'POST', body: JSON.stringify({ direction: personaDirection }),
      });
      if (selectedGuild === selectedGuildRef.current) {
        setPersonaPreview({ previewId: data.previewId as string, persona: data.persona as Persona });
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : 'AIの性格を生成できませんでした');
      addToast('AIの性格を生成できませんでした', 'error');
    } finally { setPersonaPreviewBusy(false); }
  };

  const applyPersonaPreview = async () => {
    const selectedGuild = guildId;
    if (!selectedGuild || !personaPreview || personaApplyBusy) return;
    setPersonaApplyBusy(true);
    try {
      const data = await readJson(`/api/staff/ai/${selectedGuild}/personality/persona/apply`, {
        method: 'POST', body: JSON.stringify({ previewId: personaPreview.previewId }),
      });
      if (selectedGuild === selectedGuildRef.current) {
        setPersonality(data.personality as Personality);
        setPersonaPreview(null);
        addToast('新しい性格を適用しました', 'success');
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : 'AIの性格を適用できませんでした');
      addToast('AIの性格を適用できませんでした', 'error');
    } finally { setPersonaApplyBusy(false); }
  };

  const resetPersonality = async () => {
    const selectedGuild = guildId;
    if (!selectedGuild || personalityBusy) return;
    setPersonalityBusy(true);
    try {
      const data = await readJson(`/api/staff/ai/${selectedGuild}/personality/reset`, { method: 'POST' });
      if (selectedGuild === selectedGuildRef.current) {
        const next = data.personality as Personality;
        setPersonality(next);
        personalityDirtyRef.current = false; setPersonalityDirty(false);
        setPersonalityDraft({
          learningEnabled: next.learningEnabled, tone: next.tone, humor: next.humor,
          emoji: next.emoji, verbosity: next.verbosity, customInstructions: next.customInstructions,
        });
        setResetPersonalityConfirm(false);
        addToast('AIの性格設定を初期状態に戻しました', 'success');
        await refresh(selectedGuild);
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : 'AIの性格設定を初期化できませんでした');
      addToast('AIの性格設定を初期化できませんでした', 'error');
    } finally { setPersonalityBusy(false); }
  };

  useEffect(() => {
    if (!guildId) return;
    setMetrics(zero); setMemories([]); setCustomMemos([]); setEditing(null); setSearch(''); setLastUpdated(null);
    setMemberMemos([]); setMemberMemoCanManage(false); setMemberMemoSearch(''); setMemberMemoBusyId(null);
    setPersonaPreview(null); setPersonaDirection('');
    personalityDirtyRef.current = false; setPersonalityDirty(false);
    void refresh(guildId, true);
    const timer = window.setInterval(() => void refresh(guildId), 30_000);
    return () => window.clearInterval(timer);
  }, [guildId, refresh]);

  const save = async (item: Memory) => {
    if (!draft.trim() || busy || draft.length > 6000) return;
    setBusy(true);
    try {
      await readJson(`/api/staff/ai/${guildId}/memories/${encodeURIComponent(item.id)}`, {
        method: 'PUT', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ content: draft.trim() }),
      });
      setEditing(null);
      addToast('メモリーを保存しました', 'success');
      await refresh(guildId);
    } catch (e) { setError(String(e)); addToast('保存に失敗しました', 'error'); }
    finally { setBusy(false); }
  };

  const remove = async () => {
    if (!deleting || busy || (deleting === 'all' && confirmation !== 'すべて削除')) return;
    const target = deleting;
    setBusy(true);
    try {
      await readJson(`/api/staff/ai/${guildId}/memories${target === 'all' ? '' : '/' + encodeURIComponent(target.id)}`, {
        method: 'DELETE',
      });
      setDeleting(null); setConfirmation(''); setEditing(null);
      addToast(target === 'all' ? 'メモリーをすべて削除しました' : 'メモリーを削除しました', 'success');
      await refresh(guildId);
    } catch (e) { setError(String(e)); addToast('削除に失敗しました', 'error'); }
    finally { setBusy(false); }
  };

  const deleteMemberMemo = async (item: MemberMemoItem) => {
    if (memberMemoBusyId) return;
    if (!window.confirm(`${item.name} さんのメンバーメモを削除しますか？\n間違ったメモを消すための操作です。そのメンバーが再び活発に発言すると、観測からメモが作り直されることがあります。`)) return;
    setMemberMemoBusyId(item.userId);
    try {
      await readJson(`/api/staff/ai/${guildId}/member-memos/${encodeURIComponent(item.userId)}`, { method: 'DELETE' });
      setMemberMemos(list => list.filter(memo => memo.userId !== item.userId));
      addToast('メンバーメモを削除しました', 'success');
    } catch (e) {
      setError(e instanceof Error ? e.message : 'メンバーメモを削除できませんでした');
      addToast('メンバーメモを削除できませんでした', 'error');
    } finally { setMemberMemoBusyId(null); }
  };

  const filteredMemberMemos = useMemo(() => {
    const query = memberMemoSearch.trim().toLocaleLowerCase();
    if (!query) return memberMemos;
    return memberMemos.filter(memo => [memo.name, memo.memo, memo.userId]
      .join(' ').toLocaleLowerCase().includes(query));
  }, [memberMemos, memberMemoSearch]);

  const filtered = useMemo(() => memories
    .filter(item => item.kind === tab && [item.title, item.content, item.userId || '', item.day || '']
      .join(' ').toLocaleLowerCase().includes(search.trim().toLocaleLowerCase()))
    .sort((a, b) => b.updatedAt.localeCompare(a.updatedAt)), [memories, search, tab]);
  const counts = useMemo(() => ({
    daily: memories.filter(item => item.kind === 'daily').length,
    user: memories.filter(item => item.kind === 'user').length,
  }), [memories]);
  const speed = metrics.generatedSeconds > 0 && (metrics.timedOutputTokens ?? 0) > 0
    ? (metrics.timedOutputTokens as number) / metrics.generatedSeconds : null;
  const cache = metrics.cacheInputTokens > 0 ? metrics.cacheHitTokens / metrics.cacheInputTokens * 100 : null;
  const selected = guilds.find(g => g.id === guildId);

  return <div className={`${ui.page} ${styles.pageRoot}`}>
    <header className={ui.hero}>
      <div>
        <Link to="/staff" className={ui.muted}>{icon('arrow_back')} スタッフ運用に戻る</Link>
        <div style={{ marginTop: 14 }}><span className={ui.eyebrow}>{icon('auto_awesome')} AI Operations</span></div>
        <h1>Staff AI</h1>
        <p>会話の利用状況、日々の振り返りとAI利用履歴をまとめて管理。</p>
      </div>
      <div className={ui.heroActions}>
        <label className={ui.label}>対象サーバー
          <select className={ui.select} aria-label="管理対象サーバー" value={guildId}
            onChange={e => setGuildId(e.target.value)} disabled={loadingGuilds}>
            {!guildId && <option value="">サーバーを選択</option>}
            {guilds.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
          </select>
        </label>
        <button type="button" className={`${ui.button} ${ui.serverRefreshButton}`} onClick={() => void refresh(guildId, true)} disabled={loading || !guildId}>
          {icon('refresh')} {loading ? '更新中…' : '更新'}
        </button>
      </div>
    </header>

    {error && <div className={ui.error} role="alert">{icon('error_outline')} <span>{error}</span></div>}
    {loadingGuilds ? <div className={ui.state} role="status">{icon('hourglass_top')}<p>サーバー情報を読み込んでいます…</p></div>
      : !guildId ? <div className={ui.state}>{icon('dns')}<h3>管理できるサーバーがありません</h3><p>Staff権限のあるサーバーでログインしてください。</p></div>
        : <>
          <section aria-label="Staff AIの累計利用統計">
            <div className={ui.sectionHeader} style={{ padding: '0 0 15px', borderBottom: 0 }}>
              <div><h2>利用状況</h2><p>{selected?.name || 'サーバー'} の累計統計</p></div>
              <span className={ui.badge}>{icon('schedule')} {lastUpdated ? `更新 ${lastUpdated.toLocaleTimeString('ja-JP', {hour:'2-digit',minute:'2-digit'})}` : '集計中'}</span>
            </div>
            <div className={ui.metrics}>
              {[
                { label: '総トークン', value: fmt(metrics.totalTokens), meta: `入力 ${fmt(metrics.inputTokens)} / 出力 ${fmt(metrics.outputTokens)}`, pict: 'analytics' },
                { label: '生成速度', value: speed === null ? '—' : speed.toFixed(1), suffix: speed === null ? '' : 'tok/s', meta: '生成時間の分かる出力トークン ÷ 生成時間（prefill除く）', pict: 'speed' },
                { label: 'KVヒット率', value: cache === null ? '—' : cache.toFixed(1) + '%', meta: cache === null ? '取得可能なヒット統計はありません' : `${fmt(metrics.cacheHitTokens)} / ${fmt(metrics.cacheInputTokens)} トークン`, pict: 'memory', percent: cache },
                { label: 'リクエスト数', value: fmt(metrics.requests), meta: metrics.startedAt ? `${new Date(metrics.startedAt).toLocaleString('ja-JP')} 以降・全AI経路` : '集計開始前', pict: 'forum' },
              ].map(m => <div className={ui.metric} key={m.label}>
                <div className={ui.metricTop}><span className={ui.metricLabel}>{m.label}</span><span className={ui.metricIcon}>{icon(m.pict)}</span></div>
                <strong className={ui.metricValue}>{m.value} {m.suffix && <small>{m.suffix}</small>}</strong>
                {'percent' in m && m.percent !== null && <div className={ui.track}><i className={ui.trackFill} style={{ width: Math.min(100, Math.max(0,m.percent || 0)) + '%' }} /></div>}
                <span className={ui.metricMeta}>{m.meta}</span>
              </div>)}
            </div>
            {metrics.byPurpose && Object.keys(metrics.byPurpose).length > 0 && (
              <ClampText className={ui.muted} style={{ marginTop: 10 }} text={`用途別: ${Object.entries(metrics.byPurpose)
                .sort((a, b) => b[1].requests - a[1].requests)
                .map(([purpose, totals]) => `${purposeLabels[purpose] ?? purpose} ${fmt(totals.requests)}件・${fmt(totals.totalTokens)}`)
                .join(' / ')}`} />
            )}
          </section>

          <CollapsibleSection
            eyebrow={<span className={ui.eyebrow}>{icon('psychology')} サーバーの学習 / 共通の話し方</span>}
            title="サーバーになじむAI"
            description="口調・ユーモア・絵文字・回答の詳しさ・追加調整はAIChannelと /staff ai で共通です。サーバーの雰囲気はサーバー内の会話（dot常駐の観測）から学び、その傾向も両方の返答に反映します。会話の学習元とメモリーは機能ごとに分けて管理します。"
            badge={<span className={`${ui.badge} ${personalityDraft.learningEnabled ? ui.badgeSuccess : ui.badgeWarn}`}>
              {icon(personalityDraft.learningEnabled ? 'auto_awesome' : 'pause_circle')}
              {personalityDraft.learningEnabled ? '学習中' : '自動学習停止中'}
            </span>}
          >
            <div className={ui.personalityBody}>
              <div className={ui.personalityGrid}>
                <label className={ui.label}>基本の口調
                  <select className={ui.select} value={personalityDraft.tone} onChange={e => updatePersonalityDraft({ ...personalityDraft, tone: e.target.value as PersonalitySettings['tone'] })}>
                    <option value="auto">サーバーに合わせる</option><option value="casual">親しみやすく</option>
                    <option value="balanced">自然で中立</option><option value="polite">丁寧に</option>
                  </select>
                </label>
                <label className={ui.label}>ユーモア
                  <select className={ui.select} value={personalityDraft.humor} onChange={e => updatePersonalityDraft({ ...personalityDraft, humor: e.target.value as PersonalitySettings['humor'] })}>
                    <option value="auto">学習に合わせる</option><option value="low">控えめ</option>
                    <option value="medium">ほどよく</option><option value="high">多め</option>
                  </select>
                </label>
                <label className={ui.label}>絵文字
                  <select className={ui.select} value={personalityDraft.emoji} onChange={e => updatePersonalityDraft({ ...personalityDraft, emoji: e.target.value as PersonalitySettings['emoji'] })}>
                    <option value="auto">学習に合わせる</option><option value="low">控えめ</option>
                    <option value="medium">ほどよく</option><option value="high">多め</option>
                  </select>
                </label>
                <label className={ui.label}>回答の詳しさ
                  <select className={ui.select} value={personalityDraft.verbosity} onChange={e => updatePersonalityDraft({ ...personalityDraft, verbosity: e.target.value as PersonalitySettings['verbosity'] })}>
                    <option value="auto">会話に合わせる</option><option value="brief">短く</option>
                    <option value="normal">標準</option><option value="detailed">詳しく</option>
                  </select>
                </label>
              </div>
              <label className={ui.label}>Staffからの追加調整
                <textarea className={ui.textarea} maxLength={1200} rows={3} value={personalityDraft.customInstructions}
                  placeholder="例: Minecraftの話題では少しくだけた口調にする。結論を先に伝える。"
                  onChange={e => updatePersonalityDraft({ ...personalityDraft, customInstructions: e.target.value })} />
                <span className={ui.muted}>{personalityDraft.customInstructions.length} / 1200文字</span>
              </label>
              <div className={ui.personalityInsight}>
                <strong>{icon('theater_comedy')} AIの性格（ロールプレイ定義）</strong>
                {personality.persona ? <>
                  <PersonaDetails persona={personality.persona} />
                  <span className={ui.muted}>
                    {personality.persona.source === 'generated' ? 'AIが初期化時に自分で決めた性格です' : 'AI生成に失敗したため標準の性格を使用中です'}
                    （{new Date(personality.persona.generatedAt).toLocaleString('ja-JP')}）。AIChannelと /staff ai の両方に適用されます。
                  </span>
                </> : <p>AIが性格を決めています。まもなく表示されます。</p>}
                <div className={ui.personalityActions}>
                  <button type="button" className={ui.button} disabled={personaBusy} onClick={() => void regeneratePersona()}>
                    {icon('autorenew')} {personaBusy ? '生成中…' : '性格を再生成'}
                  </button>
                </div>
                <label className={ui.label}>性格の方向（任意）
                  <textarea className={ui.textarea} maxLength={300} rows={2} value={personaDirection}
                    placeholder="例: もっと毒舌でツッコミ寄りに。関西弁のノリを強めに。"
                    onChange={e => setPersonaDirection(e.target.value)} />
                  <span className={ui.muted}>{personaDirection.length} / 300文字。現在の性格をもとに、方向に寄せて作り直します。生成・適用にはサーバー管理者権限が必要です。</span>
                </label>
                <div className={ui.personalityActions}>
                  <button type="button" className={ui.button} disabled={personaPreviewBusy} onClick={() => void previewPersona()}>
                    {icon('science')} {personaPreviewBusy ? '生成中…' : '方向を指定して生成（プレビュー）'}
                  </button>
                </div>
                {personaPreview ? <div className={ui.personalityInsight}>
                  <strong>{icon('preview')} 新しい性格のプレビュー（未適用）</strong>
                  <PersonaDetails persona={personaPreview.persona} />
                  <span className={ui.muted}>プレビューは10分間だけ有効です。適用すると現在の性格と置き換わります。</span>
                  <div className={ui.personalityActions}>
                    <button type="button" className={ui.buttonPrimary} disabled={personaApplyBusy} onClick={() => void applyPersonaPreview()}>
                      {icon('check')} {personaApplyBusy ? '適用中…' : 'この性格を適用'}
                    </button>
                    <button type="button" className={ui.button} disabled={personaApplyBusy} onClick={() => setPersonaPreview(null)}>
                      {icon('close')} やめる
                    </button>
                  </div>
                </div> : null}
              </div>
              <div className={ui.personalityInsight}>
                <strong>{icon('auto_awesome')} サーバーの雰囲気</strong>
                <ClampText text={personality.learnedSummary || 'まだ十分な傾向はありません。サーバーで会話が増えると、複数人に共通する話題や口調だけを少しずつ学びます。'} />
                <span className={ui.muted}>観測した発言: {fmt(personality.learnedMessageCount)} 件</span>
              </div>
              <div className={ui.personalityFooter}>
                <label className={ui.personalityToggle}>
                  <input type="checkbox" checked={personalityDraft.learningEnabled}
                    onChange={e => updatePersonalityDraft({ ...personalityDraft, learningEnabled: e.target.checked })} />
                  会話から自動で学ぶ
                </label>
                <div className={ui.personalityActions}>
                  <button type="button" className={ui.button} disabled={personalityBusy} onClick={() => setResetPersonalityConfirm(true)}>
                    {icon('restart_alt')} 初期状態に戻す
                  </button>
                  <button type="button" className={ui.buttonPrimary} disabled={personalityBusy || !personalityDirty} onClick={() => void savePersonality()}>
                    {icon('save')} {personalityBusy ? '保存中…' : '話し方を保存'}
                  </button>
                </div>
              </div>
            </div>
          </CollapsibleSection>

          <CollapsibleSection
            eyebrow={<span className={ui.eyebrow}>{icon('group')} メンバーメモ</span>}
            title="メンバーメモ"
            description="dot常駐が観測から学習した、メンバーごとの短いメモです。常駐の応答では、その人が会話に出てきたときだけ使われます。センシティブな属性の推測は記録しません。"
            badge={memberMemos.length ? <span className={ui.badge}>{icon('group')} {memberMemos.length} 人</span> : undefined}
          >
            <div className={ui.toolbar}>
              <label className={ui.searchWrap}>{icon('search')}<input aria-label="メンバーメモ検索" placeholder="名前・メモ本文を検索" value={memberMemoSearch} onChange={e => setMemberMemoSearch(e.target.value)} /></label>
              <span className={ui.muted}>{filteredMemberMemos.length} 人表示</span>
            </div>
            {memberMemos.length ? (filteredMemberMemos.length ? <div className={styles.memoList}>
              {filteredMemberMemos.map(memo => <article className={styles.memoItem} key={memo.userId}>
                <div>
                  <h3 className={styles.memoName}>{memo.name}</h3>
                  <div className={styles.memoMeta}>
                    <span>観測した発言: {fmt(memo.messageCount)} 件</span>
                    {memo.memo ? <span>更新 {new Date(memo.updatedAt).toLocaleString('ja-JP')}</span> : null}
                    {memo.lastSeenAt > 0 ? <span>最終観測 {new Date(memo.lastSeenAt).toLocaleString('ja-JP')}</span> : null}
                  </div>
                  {memo.memo
                    ? <p className={styles.memoBody}>{memo.memo}</p>
                    : <p className={styles.memoEmpty}>メモはまだ生成されていません（発言の観測だけが記録されています）。</p>}
                </div>
                {memberMemoCanManage ? <div className={styles.memoActions}>
                  <button type="button" className={ui.buttonDanger} disabled={memberMemoBusyId !== null}
                    onClick={() => void deleteMemberMemo(memo)} aria-label={`${memo.name} のメンバーメモを削除`}>
                    {icon('delete_outline')} {memberMemoBusyId === memo.userId ? '削除中…' : '削除'}
                  </button>
                </div> : null}
              </article>)}
            </div> : <div className={ui.emptyInner}>
              <div className={ui.emptyIcon}>{icon('search_off')}</div>
              <h3>一致するメンバーがいません</h3>
              <p>検索条件を変えてみてください。</p>
            </div>) : <div className={ui.emptyInner}>
              <div className={ui.emptyIcon}>{icon('group')}</div>
              <h3>まだメモがありません</h3>
              <p>dot常駐の観測から学習されます。サーバーで会話が増えると、活発なメンバーのメモがここに表示されます。</p>
            </div>}
          </CollapsibleSection>

          <CollapsibleSection
            eyebrow={<span className={ui.eyebrow}>Custom memos</span>}
            title="カスタムメモ"
            description="Discordの /staff ai に「○○を共有メモに保存して」と依頼すると、ここに表示されます。"
          >
            {customMemos.length ? <div className={ui.list}>{customMemos.map(memo => <article className={ui.listItem} key={memo.id}><div>
              <h3 className={ui.listTitle}>{memo.title || '無題のメモ'}</h3>
              <div className={ui.listMeta}><span>{memo.authorName || 'Staff'}</span><span>{new Date(memo.updatedAt || memo.createdAt).toLocaleString('ja-JP')}</span></div>
              <ClampText className={ui.listBody} text={memo.content} />
            </div></article>)}</div> : <div className={ui.emptyInner}><h3>まだカスタムメモはありません</h3><p>日次記録や履歴をリセットしても、カスタムメモは保持されます。</p></div>}
          </CollapsibleSection>
          <CollapsibleSection
            eyebrow={<span className={ui.eyebrow}>Memory workspace</span>}
            title="メモリーライブラリ"
            description="通常のサーバー会話を蓄積し、12時間ごとにチャンネル別の会話を確認し、バックグラウンドで出来事を更新します。/staff aiの利用は不要です。AIChannelとStaff AIは共通の話し方設定を使います。"
            headerActions={<button type="button" className={ui.buttonDanger} disabled={busy || (!memories.length && !personality.learnedSummary)} onClick={() => { setDeleting('all'); setConfirmation(''); }}>
              {icon('delete_outline')} 全件削除
            </button>}
          >
            <div className={ui.toolbar}>
              <div className={ui.tabs} role="tablist" aria-label="メモリー種別">
                <button role="tab" aria-selected={tab === 'daily'} type="button" className={`${ui.tab} ${tab === 'daily' ? ui.tabActive : ''}`}>
                  出来事 <small>{counts.daily}</small>
                </button>
              </div>
              <label className={ui.searchWrap}>{icon('search')}<input aria-label="メモリー検索" placeholder="タイトル・本文を検索" value={search} onChange={e => setSearch(e.target.value)} /></label>
              <span className={ui.muted}>{filtered.length} 件表示</span>
            </div>
            {loading ? <div className={ui.panelBody}><div className={ui.skeleton}/></div>
              : filtered.length ? <div className={ui.list} role="tabpanel">
                {filtered.map(item => <article className={ui.listItem} key={item.id}>
                  <div>
                    <h3 className={ui.listTitle}>{item.title}</h3>
                    <div className={ui.listMeta}>
                      <span>{item.day || (item.userId ? 'User ' + item.userId : '')}</span>
                      {item.sourceChannelName && <span>#{item.sourceChannelName} の履歴</span>}
                      <span>{fmt(item.evidenceCount)} 件の会話</span>
                      <span>更新 {new Date(item.updatedAt).toLocaleDateString('ja-JP')}</span>
                      {item.editedByStaff && <span className={`${ui.badge} ${ui.badgeSuccess}`}>Staff編集済み</span>}
                    </div>
                    {editing === item.id ? <>
                      <label className={ui.label} style={{ marginTop: 15 }}>メモリー本文
                        <textarea className={ui.textarea} maxLength={6000} value={draft} rows={7} onChange={e => setDraft(e.target.value)} />
                      </label>
                      <div className={ui.editorActions}>
                        <span className={ui.muted} style={{ marginRight: 'auto', alignSelf: 'center' }}>{draft.length} / 6000文字</span>
                        <button type="button" className={ui.button} onClick={() => setEditing(null)}>キャンセル</button>
                        <button type="button" className={ui.buttonPrimary} disabled={busy || !draft.trim()} onClick={() => void save(item)}>{icon('save')} 保存</button>
                      </div>
                    </> : <>
                      <ClampText className={ui.listBody} text={item.content} />
                      {item.kind === 'user' && item.publicInterests && <p className={ui.muted} style={{ marginTop: 12 }}>
                        {icon('public')} 公開可能な趣味: {item.publicInterests}
                      </p>}
                    </>}
                  </div>
                  <div className={ui.listActions}>
                    <button className={ui.button} type="button" disabled={busy || editing === item.id}
                      onClick={() => { setEditing(item.id); setDraft(item.content); }}>{icon('edit')} 編集</button>
                    <button className={ui.buttonDanger} type="button" disabled={busy} onClick={() => { setDeleting(item); setConfirmation(''); }} aria-label={item.title + 'を削除'}>{icon('delete_outline')}</button>
                  </div>
                </article>)}
              </div> : <div className={ui.emptyInner}>
                <div className={ui.emptyIcon}>{icon(search ? 'search_off' : tab === 'daily' ? 'event_note' : 'person_search')}</div>
                <h3>{search ? '一致するメモリーがありません' : 'まだメモリーがありません'}</h3>
                <p>{search ? '検索条件を変えてみてください。' : tab === 'daily' ? 'チャンネル履歴や/staff aiの会話から、日々の振り返りをバックグラウンドで作成します。' : 'Discordからカスタムメモを作成できます。'}</p>
              </div>}
          </CollapsibleSection>
          <CollapsibleSection
            eyebrow={<span className={ui.eyebrow}>{icon('settings')} その他</span>}
            title="その他・履歴のリセット"
            description="総履歴のリセットと、メモリーの取り扱いについて。"
          >
            <div className={styles.sectionPad}>
              <div className={ui.notice}>
                {icon('delete_forever')}
                <div><strong>総履歴のリセット</strong><p>このサーバーのStaff AI統計、会話履歴、日次記録を削除します。元に戻せません。</p>
                  <button type="button" className={ui.buttonDanger} onClick={async () => {
                    if (!window.confirm('このサーバーのAI履歴・累計統計を完全にリセットしますか？元には戻せません。')) return;
                    try {
                      await readJson(`/api/staff/ai/${guildId}/history/reset`, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({confirm:'RESET'})});
                      await refresh(guildId, true); addToast('総履歴をリセットしました', 'success');
                    } catch (error) { addToast(error instanceof Error ? error.message : 'リセットに失敗しました', 'error'); }
                  }}>総履歴をリセット</button>
                </div>
              </div>
              <div className={ui.notice}>{icon('verified_user')} <div><strong style={{ color: 'var(--app-ink)' }}>メモリーの取り扱い</strong><p>メモリーはサーバーごとに分離して保存します。通常のサーバー会話をもとに、12時間ごとにメモリーを更新します。興味・活動・話し方は会話で観測できる範囲に限り、私的情報や性格診断は保存しません。AIChannelとStaff AIは共通の話し方設定を使い、会話履歴から日次記録を作成します。</p></div></div>
            </div>
          </CollapsibleSection>
        </>}

    {deleting && <div className={ui.modalBackdrop} role="presentation" onMouseDown={e => { if (e.target === e.currentTarget && !busy) setDeleting(null); }}>
      <div className={ui.dialog} role="alertdialog" aria-modal="true" aria-labelledby="staff-ai-delete-title" aria-describedby="staff-ai-delete-description">
        <span className={ui.eyebrow}>{icon('warning_amber')} 削除の確認</span>
        <h2 id="staff-ai-delete-title">{deleting === 'all' ? 'すべてのメモリーを削除しますか？' : 'このメモリーを削除しますか？'}</h2>
        <p id="staff-ai-delete-description">{deleting === 'all' ? `${memories.length} 件の記憶と、学習したサーバーの雰囲気を削除します。Staffが設定した口調は残ります。この操作は元に戻せません。` : `「${deleting.title}」を削除します。この操作は元に戻せません。`}</p>
        {deleting === 'all' && <label className={ui.label}>確認のため「すべて削除」と入力
          <input className={ui.input} autoFocus value={confirmation} onChange={e => setConfirmation(e.target.value)} placeholder="すべて削除" />
        </label>}
        <div className={ui.dialogActions}>
          <button className={ui.button} type="button" disabled={busy} onClick={() => setDeleting(null)}>キャンセル</button>
          <button className={ui.buttonDanger} type="button" disabled={busy || (deleting === 'all' && (confirmation !== 'すべて削除'))} onClick={() => void remove()}>
            {busy ? '削除中…' : '削除する'}
          </button>
        </div>
      </div>
    </div>}
    {resetPersonalityConfirm && <div className={ui.modalBackdrop} role="presentation" onMouseDown={e => { if (e.target === e.currentTarget && !personalityBusy) setResetPersonalityConfirm(false); }}>
      <div className={ui.dialog} role="alertdialog" aria-modal="true" aria-labelledby="staff-ai-personality-reset-title">
        <span className={ui.eyebrow}>{icon('restart_alt')} 性格設定の初期化</span>
        <h2 id="staff-ai-personality-reset-title">このサーバーのAI設定を初期状態に戻しますか？</h2>
        <p>Staffが調整した共通の話し方と学習済みの雰囲気を初期化します。ユーザー別プロフィールと出来事は残ります。</p>
        <div className={ui.dialogActions}>
          <button className={ui.button} type="button" disabled={personalityBusy} onClick={() => setResetPersonalityConfirm(false)}>キャンセル</button>
          <button className={ui.buttonDanger} type="button" disabled={personalityBusy} onClick={() => void resetPersonality()}>
            {personalityBusy ? '初期化中…' : '初期状態に戻す'}
          </button>
        </div>
      </div>
    </div>}
  </div>;
};
export default StaffAIPage;
